import re
from datetime import datetime, timezone

_RETRYABLE_STATUSES = {429, 502, 503, 504}
_IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
_DEFAULT_PROFILE = (5, 8.0, 30.0)
_PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}
_MONTHS = {
    name: index + 1
    for index, name in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    )
}
_HTTP_DATE = re.compile(
    r"(Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\d{2}) ([A-Z][a-z]{2}) (\d{4}) "
    r"(\d{2}):(\d{2}):(\d{2}) GMT"
)


def _header(headers, name):
    for key, value in (headers or {}).items():
        if key.lower() == name:
            return value
    return None


def _retry_after_seconds(value, now):
    if value is None:
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value):
        return float(int(value))
    match = _HTTP_DATE.fullmatch(value)
    if not match or match.group(3) not in _MONTHS:
        return None
    try:
        moment = datetime(
            int(match.group(4)),
            _MONTHS[match.group(3)],
            int(match.group(2)),
            int(match.group(5)),
            int(match.group(6)),
            int(match.group(7)),
            tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    return max(0.0, (moment - now).total_seconds())
EOF
