src=open('shipclient/retry.py').read()
impl=open('/tmp/impl.py').read()
src=src.replace("from datetime import datetime\n", impl)
src=src.replace("    raise NotImplementedError\n", '''    if status is not None and status not in _RETRYABLE_STATUSES:
        return None
    method = method.upper()
    if method not in _IDEMPOTENT_METHODS:
        key = _header(request_headers, "idempotency-key")
        if method not in ("POST", "PATCH") or not key or not key.strip():
            return None

    service = (_header(request_headers, "x-service") or "").strip().lower()
    max_attempts, cap, max_retry_after = _PROFILES.get(service, _DEFAULT_PROFILE)
    if attempt >= max_attempts:
        return None

    delay = min(0.25 * 2 ** (attempt - 1), cap)
    if status in (429, 503):
        wait = _retry_after_seconds(_header(response_headers, "retry-after"), now)
        if wait is not None:
            if wait > max_retry_after:
                return None
            delay = max(delay, wait)
    return delay
''')
open('shipclient/retry.py','w').write(src)
EOF
